using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
namespace MasterMiao.Weld {
 public sealed class WeldMember {public string Id{get;set;}public string Reference{get;set;}public string Instance{get;set;}public string File{get;set;}public string Configuration{get;set;}public string Marker{get;set;}public double[] Position{get;set;}public double[] Anchor{get;set;}}
 public sealed class WeldGroup {public string Id{get;set;}public string Code{get;set;}public string Name{get;set;}public int Color{get;set;}public bool MarkersVisible{get;set;}public string Remark{get;set;}public List<WeldMember> Members{get;set;}public WeldGroup(){Members=new List<WeldMember>();MarkersVisible=true;}}
 public sealed class WeldProject {public int Version{get;set;}public string AssemblyPath{get;set;}public string Configuration{get;set;}public int NextNumber{get;set;}public List<WeldGroup> Groups{get;set;}public WeldProject(){Version=1;NextNumber=1;Groups=new List<WeldGroup>();}}
 public sealed class WeldStore {
  public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};public readonly string Root;
  public WeldStore(string root=null){Root=root??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MasterMiao","WeldGroups");}
  public string PathFor(string assembly,string configuration){using(var sha=SHA256.Create()){var hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(assembly).ToUpperInvariant()+"\n"+configuration))).Replace("-","");return Path.Combine(Root,hash+".json");}}
  public WeldProject Load(string assembly,string configuration){string path=PathFor(assembly,configuration);if(!File.Exists(path))return new WeldProject{AssemblyPath=assembly,Configuration=configuration};var p=Json.Deserialize<WeldProject>(File.ReadAllText(path));Validate(p);if(!string.Equals(Path.GetFullPath(p.AssemblyPath),Path.GetFullPath(assembly),StringComparison.OrdinalIgnoreCase)||p.Configuration!=configuration)throw new IOException("焊接组数据与当前装配体不匹配。");return p;}
  public void Save(WeldProject p){Validate(p);Directory.CreateDirectory(Root);string path=PathFor(p.AssemblyPath,p.Configuration),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,Json.Serialize(p),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  public static void Validate(WeldProject p){if(p==null||p.Version!=1||p.Groups==null||string.IsNullOrWhiteSpace(p.AssemblyPath)||p.Configuration==null)throw new IOException("焊接组数据格式无效，未覆盖原文件。");var groupIds=new HashSet<string>();var codes=new HashSet<string>();foreach(var g in p.Groups){if(string.IsNullOrWhiteSpace(g.Id)||!groupIds.Add(g.Id)||!codes.Add(g.Code)||string.IsNullOrWhiteSpace(g.Name)||g.Members==null)throw new IOException("焊接组编号或名称无效。");var members=new HashSet<string>();foreach(var m in g.Members)if(string.IsNullOrWhiteSpace(m.Id)||string.IsNullOrWhiteSpace(m.Reference)||!members.Add(m.Id))throw new IOException("焊接组成员引用无效或重复。");}}
  public static WeldGroup AddGroup(WeldProject p,string name,int color){name=(name??"").Trim();if(name.Length==0)throw new ArgumentException("请输入焊接组名称。");if(p.Groups.Any(g=>g.Name.Equals(name,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("已有同名焊接组。");if(p.Groups.Any(g=>g.Color==color))throw new ArgumentException("该颜色已用于其他焊接组，请换一种颜色。");var group=new WeldGroup{Id=Guid.NewGuid().ToString("N"),Code="W"+(p.NextNumber++).ToString("D2"),Name=name,Color=color};p.Groups.Add(group);return group;}
  public static WeldMember AddMember(WeldGroup group,WeldMember member){var old=group.Members.FirstOrDefault(m=>m.Reference==member.Reference);if(old!=null)return old;var copy=new WeldMember{Id=member.Id,Reference=member.Reference,Instance=member.Instance,File=member.File,Configuration=member.Configuration};group.Members.Add(copy);return copy;}
 }
}
